import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpecialElite = makeLoadFont('SpecialElite');

// Load font at module level to ensure it's ready before frame 0
const { fontFamily: specialEliteFamily } = loadSpecialElite();



export type TypewriterEffectProps = Record<string, any>;

const TypewriterEffect: React.FC<TypewriterEffectProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  text = "what are you most\nproud of about\nCallejas Windows & Doors?",
  textColor = "#111111",
  charactersPerSecond = 20,
  cursorBlinkRate = 15,
  startDelayInSeconds = 0.5,
  fontSize = 90,
  maxWidthPercentage = 0.75,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Canvas-relative scaling factor
  const s = Math.min(width, height) / 1080;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Typewriter Timing Logic
  const startDelayFrames = Math.round(startDelayInSeconds * fps);
  const totalCharacters = text.length;
  const typingDurationFrames = (totalCharacters / charactersPerSecond) * fps;
  const endTypingFrame = startDelayFrames + typingDurationFrames;

  // Calculate how many characters should be visible on the current frame
  const visibleCharsCount = interpolate(
    frame,
    [startDelayFrames, endTypingFrame],
    [0, totalCharacters],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const currentVisibleChars = Math.floor(visibleCharsCount);
  const currentText = text.substring(0, currentVisibleChars);

  // Cursor logic: solid while actively typing, blinking otherwise
  const isActivelyTyping = frame >= startDelayFrames && frame <= endTypingFrame;
  const isBlinkOn = Math.floor(frame / cursorBlinkRate) % 2 === 0;
  const showCursor = isActivelyTyping ? true : isBlinkOn;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: width * maxWidthPercentage,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
        }}
      >
        <div
          style={{
            fontFamily: specialEliteFamily,
            fontSize: fontSize * s,
            color: textColor,
            lineHeight: 1.4,
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
            // Remove transition to ensure frame-pure animation
            transition: "none",
          }}
        >
          {currentText}
          <span
            style={{
              opacity: showCursor ? 1 : 0,
              // Slightly thinner font weight for the cursor pipe character looks more realistic
              fontWeight: 300, 
              transition: "none",
            }}
          >
            |
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TypewriterEffect;